      {"FAA": "Fish Amino Acid"},
      {"LAB": "Lactic Acid Bacteria"},
      {"Ws-K": "Water Soluble Potassium"},
      {"Ws-PA": "Water-Soluble Phosphoric Acid"},
      {"Ws-Ca": "Water-Soluble Calcium"},
      {"Ws-CaPo": "Water-Soluble Calcium Phosphate"},
